<template><section class="page"><AdminNav/><header><p class="eyebrow">Resident service requests</p><h1>Cleanup requests</h1><p>Review locations submitted by residents and update them as the team responds.</p></header><p v-if="message" :class="['message',error?'error':'success']">{{message}}</p><div v-if="loading" class="empty">Loading cleanup requests…</div><div v-else class="request-grid"><article v-for="request in requests" :key="request.id" class="request"><div class="head"><div><h2>{{request.location_name}}</h2><p>{{request.address}}, {{request.suburb}}</p></div><span :class="request.status">{{request.status}}</span></div><p class="description">{{request.description}}</p><div class="resident"><strong>{{request.resident_name}}</strong><span>{{request.resident_phone}} · {{request.resident_email}}</span></div><div class="bottom"><small>Submitted {{date(request.created_at)}}<template v-if="request.preferred_date"> · Preferred: {{date(request.preferred_date)}}</template></small><select :value="request.status" @change="update(request,$event.target.value)"><option value="new">New</option><option value="reviewing">Reviewing</option><option value="scheduled">Scheduled</option><option value="completed">Completed</option></select></div></article><p v-if="!requests.length" class="empty">No cleanup requests have been submitted.</p></div></section></template>
<script setup>import{onMounted,ref}from'vue';import api from'../../api.js';import AdminNav from'./AdminNav.vue';const requests=ref([]),loading=ref(true),message=ref(''),error=ref(false);const date=v=>new Date(v).toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'});async function load(){loading.value=true;try{requests.value=(await api.get('/admin/cleanup-requests')).data}catch(e){error.value=true;message.value=e.response?.data?.message||'Unable to load requests.'}finally{loading.value=false}}async function update(request,status){try{message.value=(await api.put(`/admin/cleanup-requests/${request.id}`,{status})).data.message;error.value=false;request.status=status}catch(e){error.value=true;message.value=e.response?.data?.message||'Unable to update request.'}}onMounted(load)</script>
<style scoped>.page{width:min(1120px,100%);margin:auto;padding:2rem 1.5rem 4rem}header{margin:2rem 0 1rem}.eyebrow{color:var(--green);font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.1em;margin:0}h1,h2{color:var(--green-dark)}h1{margin:.2rem 0}header p:not(.eyebrow){color:var(--text-muted);margin:0}.request-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}.request{padding:1.2rem;background:#fff;border:1px solid var(--border);border-radius:12px}.head,.bottom{display:flex;justify-content:space-between;gap:1rem}.head h2{margin:0;font-size:1.15rem}.head p,.description{color:var(--text-muted);margin:.25rem 0}.description{min-height:3rem}.resident{display:grid;margin:.9rem 0;padding:.7rem 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}.resident span,small{color:var(--text-muted);font-size:.8rem}.head span{height:max-content;padding:.25rem .5rem;border-radius:99px;font-size:.75rem;font-weight:800;text-transform:capitalize}.new{background:#e6edf2;color:#395463}.reviewing{background:#fff1cb;color:#7a5300}.scheduled{background:#e6eefb;color:#294f88}.completed{background:#e6f5e8;color:#286033}select{padding:.35rem;border:1px solid var(--border);border-radius:6px;background:#fff}.message{padding:.7rem;border-radius:7px}.success{background:#e7f5e8;color:#286033}.error{background:#fff0f0;color:#9b2525}.empty{color:var(--text-muted);text-align:center;padding:2rem}@media(max-width:760px){.request-grid{grid-template-columns:1fr}.bottom{align-items:start;flex-direction:column}}</style>
